#include <stdint.h>
#include <stddef.h>

int gpio_set_mode(uint32_t *moder, unsigned int pin, unsigned int mode)
{
    unsigned int shift;
    uint32_t mask;

    if (moder == NULL || pin > 15u || mode > 3u) {
        return -1;
    }

    shift = pin * 2u;          /* 每个引脚占 2 位 */
    mask = 0x3u << shift;

    *moder = (*moder & ~mask) | ((uint32_t)mode << shift);
    return 0;
}
